fun {u} {P} {add sub mul div} {sqrt} {add_model} {sub_model} {mul_model} {div_model} {sqrt_model} {add' sub' mul' div'}
    {sqrt'} {add_model'} {sub_model'} {mul_model'} {div_model'} {sqrt_model'} eq k =>
  id.{u} (MixedPrecisionBlockJacobi.Arithmetic.noConfusion.{u} ⋯ ⋯ k)

fun {T} {uc} r d =>
  ∀ (k : Fin T),
    have R := MixedPrecisionBlockJacobi.choleskyPrefix r d ↑k;
    have prior := List.filter.{0} (fun i => Decidable.decide (LT.lt.{0} ↑i ↑k)) (List.finRange T);
    have rad := MixedPrecisionBlockJacobi.subtractDot.{0} r prior (d k k) (fun i => R i k) fun i => R i k;
    And (LT.lt.{0} 0 rad) (LT.lt.{0} 0 (MixedPrecisionBlockJacobi.Arithmetic.sqrt r rad))

