fun {n} T S us uc D N A Rhat =>
  HAdd.hAdd.{0, 0, 0}
    (HAdd.hAdd.{0, 0, 0}
      (HDiv.hDiv.{0, 0, 0}
        (HAdd.hAdd.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} (MixedPrecisionBlockJacobi.eta T uc D Rhat) us)
          (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us)
            (HAdd.hAdd.{0, 0, 0} (MixedPrecisionBlockJacobi.q D N)
              (HMul.hMul.{0, 0, 0} uc (MixedPrecisionBlockJacobi.p D A)))))
        (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D Rhat)))
      us)
    (HDiv.hDiv.{0, 0, 0}
      (HMul.hMul.{0, 0, 0}
        (HMul.hMul.{0, 0, 0} (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us) (HAdd.hAdd.{0, 0, 0} 1 uc))
          (MixedPrecisionBlockJacobi.c₁ n S us))
        (MixedPrecisionBlockJacobi.p D A))
      (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D Rhat)))

fun {T} {uc} r R b =>
  List.foldl.{0, 0}
    (fun y k =>
      have later := List.reverse.{0} (List.filter.{0} (fun i => Decidable.decide (LT.lt.{0} ↑k ↑i)) (List.finRange T));
      have yk :=
        MixedPrecisionBlockJacobi.Arithmetic.div r (MixedPrecisionBlockJacobi.subtractDot.{0} r later (b k) (R k) y)
          (R k k);
      Function.update.{1, 1} y k yk)
    0 (List.reverse.{0} (List.finRange T))

fun {n} T S us uc D A Rhat x b =>
  HAdd.hAdd.{0, 0, 0}
    (HMul.hMul.{0, 0, 0}
      (HAdd.hAdd.{0, 0, 0} us
        (HDiv.hDiv.{0, 0, 0}
          (HMul.hMul.{0, 0, 0}
            (HMul.hMul.{0, 0, 0} (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us) (HAdd.hAdd.{0, 0, 0} 1 uc))
              (MixedPrecisionBlockJacobi.c₁ n S us))
            (MixedPrecisionBlockJacobi.p D A))
          (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D Rhat))))
      (MixedPrecisionBlockJacobi.vectorInf x))
    (HMul.hMul.{0, 0, 0}
      (HMul.hMul.{0, 0, 0}
        (HDiv.hDiv.{0, 0, 0}
          (HMul.hMul.{0, 0, 0} (HMul.hMul.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} 1 us) (HAdd.hAdd.{0, 0, 0} 1 uc)) us)
          (HSub.hSub.{0, 0, 0} 1 (MixedPrecisionBlockJacobi.eta T uc D Rhat)))
        (MixedPrecisionBlockJacobi.matrixInf (Inv.inv.{0} D)))
      (MixedPrecisionBlockJacobi.vectorInf b))

fun n S us =>
  HAdd.hAdd.{0, 0, 0}
    (HAdd.hAdd.{0, 0, 0}
      (MixedPrecisionBlockJacobi.gamma (HSub.hSub.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} S (HDiv.hDiv.{0, 0, 0} n S)) 1) us) us)
    (HMul.hMul.{0, 0, 0} us
      (MixedPrecisionBlockJacobi.gamma (HSub.hSub.{0, 0, 0} (HAdd.hAdd.{0, 0, 0} S (HDiv.hDiv.{0, 0, 0} n S)) 1) us))

fun {T} {uc} r R b =>
  List.foldl.{0, 0}
    (fun y k =>
      have prior := List.filter.{0} (fun i => Decidable.decide (LT.lt.{0} ↑i ↑k)) (List.finRange T);
      have yk :=
        MixedPrecisionBlockJacobi.Arithmetic.div r
          (MixedPrecisionBlockJacobi.subtractDot.{0} r prior (b k) (fun i => R i k) y) (R k k);
      Function.update.{1, 1} y k yk)
    0 (List.finRange T)
